import{_ as o,o as d,c as a,a2 as t}from"./chunks/framework.CWWEQfK7.js";const u=JSON.parse('{"title":"配置故障排查：按症状找到失败位置","description":"根据启动、依赖、登录、浏览器请求、仓库访问和运行时设置的症状，逐步确认原因与修复结果。","frontmatter":{"page_id":"configuration-troubleshooting","title":"配置故障排查：按症状找到失败位置","description":"根据启动、依赖、登录、浏览器请求、仓库访问和运行时设置的症状，逐步确认原因与修复结果。"},"headers":[],"relativePath":"configuration/troubleshooting.md","filePath":"configuration/troubleshooting.md","lastUpdated":1786627803000}'),i={name:"configuration/troubleshooting.md"};function c(l,e,r,s,h,n){return d(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="配置故障排查-按症状找到失败位置" tabindex="-1">配置故障排查：按症状找到失败位置 <a class="header-anchor" href="#配置故障排查-按症状找到失败位置" aria-label="Permalink to &quot;配置故障排查：按症状找到失败位置&quot;">​</a></h1><p>排查配置问题时，先确认失败发生在哪一层：进程创建、启动生命周期、外部依赖、请求安全、仓库授权，还是运行时覆盖。不要只看 <code>/health</code> 的一个 <code>ok</code>。</p><h2 id="api-在输出监听地址前就退出" tabindex="-1">API 在输出监听地址前就退出 <a class="header-anchor" href="#api-在输出监听地址前就退出" aria-label="Permalink to &quot;API 在输出监听地址前就退出&quot;">​</a></h2><h3 id="症状" tabindex="-1">症状 <a class="header-anchor" href="#症状" aria-label="Permalink to &quot;症状&quot;">​</a></h3><p>错误提到 <code>SECRET_KEY</code>、<code>ENCRYPTION_KEY</code>、<code>MCP_KEY_PEPPER</code>、安全 Cookie、<code>OPAQUE_SERVER_SETUP</code> 或开发本地路径开关。</p><h3 id="检查顺序" tabindex="-1">检查顺序 <a class="header-anchor" href="#检查顺序" aria-label="Permalink to &quot;检查顺序&quot;">​</a></h3><ol><li>确认前三个密钥都至少 32 个字符、互不相同，并且不是 <code>change-me</code> 或 <code>replace-me</code>。</li><li>若环境是 <code>prod</code> 或 <code>production</code>，确认 <code>SESSION_COOKIE_SECURE=true</code>。</li><li>确认 <code>SESSION_COOKIE_SAMESITE</code> 是 <code>lax</code>、<code>strict</code> 或 <code>none</code>。</li><li>生产环境必须设置稳定的 <code>OPAQUE_SERVER_SETUP</code>，并关闭 <code>ALLOW_DEV_OPEN_LOCAL_REPOSITORY_PATHS</code>。</li></ol><h3 id="修复成功的标志" tabindex="-1">修复成功的标志 <a class="header-anchor" href="#修复成功的标志" aria-label="Permalink to &quot;修复成功的标志&quot;">​</a></h3><p>应用能完成创建并进入启动生命周期，不再出现同一项校验错误。此时仍需继续检查数据库连接，因为设置校验通过不代表生命周期启动完成。</p><h2 id="api-创建成功-但启动生命周期失败" tabindex="-1">API 创建成功，但启动生命周期失败 <a class="header-anchor" href="#api-创建成功-但启动生命周期失败" aria-label="Permalink to &quot;API 创建成功，但启动生命周期失败&quot;">​</a></h2><h3 id="症状-1" tabindex="-1">症状 <a class="header-anchor" href="#症状-1" aria-label="Permalink to &quot;症状&quot;">​</a></h3><p>服务在连接数据库、读取系统设置或初始化登录材料时退出，没有进入稳定监听状态。</p><h3 id="检查顺序-1" tabindex="-1">检查顺序 <a class="header-anchor" href="#检查顺序-1" aria-label="Permalink to &quot;检查顺序&quot;">​</a></h3><ol><li>核对 <code>DATABASE_URL</code> 的驱动、主机、端口、数据库名和凭据。</li><li>确认数据库已运行，并且当前账号可以读取、写入和执行升级后的表结构。</li><li>执行 <code>/opt/ershu/current/.venv/bin/ershu-db heads</code>，初始发布版本应显示迁移 head 为 <code>0003</code>。</li><li>需要升级时执行 <code>sudo systemctl restart ershu-migrate.service</code>，然后重新启动 API。</li></ol><h3 id="修复成功的标志-1" tabindex="-1">修复成功的标志 <a class="header-anchor" href="#修复成功的标志-1" aria-label="Permalink to &quot;修复成功的标志&quot;">​</a></h3><p>API 保持运行，<code>GET /health</code> 返回 <code>{&quot;status&quot;:&quot;ok&quot;}</code>，且不再在生命周期初始化阶段退出。</p><h2 id="health-正常-但依赖检查是-degraded" tabindex="-1"><code>/health</code> 正常，但依赖检查是 <code>degraded</code> <a class="header-anchor" href="#health-正常-但依赖检查是-degraded" aria-label="Permalink to &quot;`/health` 正常，但依赖检查是 `degraded`&quot;">​</a></h2><p><code>GET /health</code> 和 <code>GET /api/v1/health</code> 只返回进程存活状态。<code>GET /api/v1/health/dependencies</code> 才会检查数据库和 Milvus，而且即使降级也仍返回 HTTP 200。</p><table tabindex="0"><thead><tr><th>返回字段</th><th>说明</th><th>下一步</th></tr></thead><tbody><tr><td><code>database.ok: false</code></td><td><code>select 1</code> 失败</td><td>检查 <code>DATABASE_URL</code>、网络、凭据和数据库状态</td></tr><tr><td><code>milvus.ok: false</code></td><td>Milvus 连接或查询失败</td><td>检查 URI、令牌、数据库名和服务状态</td></tr><tr><td><code>status: degraded</code></td><td>上述至少一项失败</td><td>修复对应依赖后重新请求，直到两项都为 <code>true</code></td></tr></tbody></table><p>该端点不检查 Redis、Worker 或模型通道，不能作为整套系统就绪证明。</p><h2 id="登录返回-503-但依赖检查正常" tabindex="-1">登录返回 503，但依赖检查正常 <a class="header-anchor" href="#登录返回-503-但依赖检查正常" aria-label="Permalink to &quot;登录返回 503，但依赖检查正常&quot;">​</a></h2><p>登录限流在首次使用时连接 <code>REDIS_URL</code>。地址为空、客户端未安装、连接失败或 Redis 返回无效计数时，API 会把错误映射为 503。</p><p>检查 Redis 地址和网络后，再完成一次真实登录请求。恢复后，登录流程不会再因限流存储不可用而返回 503；依赖检查页面不会因此变化。连续失败达到当前的 5 分钟内 8 次限制后，仍会被正常限流。</p><h2 id="生产-api-返回-需要-https" tabindex="-1">生产 API 返回“需要 HTTPS” <a class="header-anchor" href="#生产-api-返回-需要-https" aria-label="Permalink to &quot;生产 API 返回“需要 HTTPS”&quot;">​</a></h2><p>生产环境下，API 会拒绝方案不是 HTTPS 的 <code>/api/</code> 与 <code>/mcp</code> 请求。若浏览器实际使用 HTTPS，但后端仍看到 HTTP：</p><ol><li>确认反向代理把原始方案正确写入转发头；</li><li>确认 <code>PROXY_HEADERS=true</code>；</li><li>把实际代理地址加入 <code>FORWARDED_ALLOW_IPS</code>，不要信任无关来源。</li></ol><p>修复后，同一 HTTPS 请求应进入正常路由；直接 HTTP 请求仍应被拒绝。</p><h2 id="浏览器写请求返回-403" tabindex="-1">浏览器写请求返回 403 <a class="header-anchor" href="#浏览器写请求返回-403" aria-label="Permalink to &quot;浏览器写请求返回 403&quot;">​</a></h2><p>先看错误内容：</p><ul><li><code>Cross-site request blocked</code>：请求的 <code>Origin</code> 或 <code>Referer</code> 不等于当前站点，也不在 <code>CORS_ORIGINS</code>；</li><li><code>csrf_invalid</code>：<code>X-Ershu-CSRF</code> 请求头缺失，或与 CSRF Cookie 不一致、签名无效。</li></ul><p>读取请求不会触发这项写请求检查。Cookie 登录的写请求必须通过 CSRF 校验；浏览器带有 <code>Origin</code> 或 <code>Referer</code> 时，来源也必须允许。Bearer 请求不使用 Cookie 身份，因此不需要 CSRF，但仍要提供有效令牌。</p><p>修复成功时，来自允许来源、带匹配 CSRF 头与 Cookie 的写请求进入业务路由；故意移除 CSRF 头时仍返回 403。</p><h2 id="远程仓库地址被拒绝" tabindex="-1">远程仓库地址被拒绝 <a class="header-anchor" href="#远程仓库地址被拒绝" aria-label="Permalink to &quot;远程仓库地址被拒绝&quot;">​</a></h2><p>错误通常能直接指出类别：</p><table tabindex="0"><thead><tr><th>错误方向</th><th>检查项</th></tr></thead><tbody><tr><td>协议不允许</td><td>默认只用 HTTPS、SSH 或 SCP 风格地址；不要为了省事打开不安全协议</td></tr><tr><td>主机不允许</td><td>非空 <code>GIT_ALLOWED_HOSTS</code> 必须匹配精确主机或通配规则</td></tr><tr><td>主机无法解析</td><td>检查 DNS 和主机拼写</td></tr><tr><td>解析到受阻地址</td><td>默认拒绝私有、回环、链路本地等地址；私有 Git 服务需要精确加入允许列表，回环仍不会放行</td></tr></tbody></table><p>运行时修改主机列表后，重新读取管理员设置，确认目标项的 <code>source</code> 和 <code>value</code>；再发起一次新的克隆或拉取。已有失败操作不会自动重放。</p><h2 id="本地仓库路径不受信任" tabindex="-1">本地仓库路径不受信任 <a class="header-anchor" href="#本地仓库路径不受信任" aria-label="Permalink to &quot;本地仓库路径不受信任&quot;">​</a></h2><p>合法路径应当位于受管缓存中、进入 <code>TRUSTED_LOCAL_PATHS</code>，或自身包含 <code>.git</code>。相对路径会按服务进程的当前工作目录解析，因此部署时更适合使用清楚的绝对路径。</p><p>开发开关 <code>ALLOW_DEV_OPEN_LOCAL_REPOSITORY_PATHS</code> 只在非生产、没有受信任列表时临时放宽路径检查。生产环境不能使用它。修复成功时，新建工作区不再报告 <code>Repository local_path is not trusted</code>，也不需要放宽整个文件系统。</p><h2 id="管理员修改设置后没有生效" tabindex="-1">管理员修改设置后没有生效 <a class="header-anchor" href="#管理员修改设置后没有生效" aria-label="Permalink to &quot;管理员修改设置后没有生效&quot;">​</a></h2><p>按下面顺序区分原因：</p><ol><li>从 <code>GET /api/v1/admin/system-settings</code> 找到目标项。</li><li>若列表中没有该项，它不是可在线覆盖设置；修改环境变量后重启对应进程。</li><li>若 <code>source</code> 是 <code>environment</code>，数据库覆盖并不存在；检查更新请求是否成功。</li><li>若 <code>source</code> 是 <code>database</code>，确认 <code>value</code> 是目标值，并记住它通常只影响后续操作。</li><li>API 实例会在启动和每 30 秒刷新；Worker 使用自己的刷新点，不能用 API 周期推断 Worker 状态。</li></ol><p>未知名称、类型错误和越界值由管理服务拒绝。不要直接向数据库写 JSON 来绕过校验；无效行会让周期刷新持续报错。</p><h2 id="开发文档页面消失" tabindex="-1">开发文档页面消失 <a class="header-anchor" href="#开发文档页面消失" aria-label="Permalink to &quot;开发文档页面消失&quot;">​</a></h2><p><code>/docs</code> 和 <code>/redoc</code> 只在 <code>ENVIRONMENT</code> 精确等于小写 <code>development</code> 时启用。<code>Development</code>、<code>dev</code> 或生产值都不会打开它们。修改后重启 API，因为环境设置已经缓存。</p><h2 id="发布包安装失败" tabindex="-1">发布包安装失败 <a class="header-anchor" href="#发布包安装失败" aria-label="Permalink to &quot;发布包安装失败&quot;">​</a></h2><p>部署脚本会读取 <code>versions.env</code>，并从 PyPI 安装当前组合指定的 <code>ershu[all]</code>。正确命令是：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/systemd/install.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --uv-bin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;$(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">command</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uv)&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>失败时先确认：</p><ol><li>当前目录来自已经发布的标签或 GitHub Release；</li><li><code>versions.env</code> 存在，<code>ERSHU_COMPOSITION_VERSION</code> 没有被修改；</li><li>错误里提到的 <code>ershu</code> 或组件版本已经在 PyPI 中可用；</li><li>当前网络和代理允许 UV 访问 PyPI；</li><li>发布包已经解压到 <code>/opt/ershu/releases/&lt;tag&gt;</code>，并且 systemd 与 <code>/usr/bin/docker</code> 可用。</li></ol><p>不要改用未固定的最新版本，也不要把本地 Wheel 或私有地址写进公开配置。发布尚未完成时，等待 <code>ershu</code> 组合包发布后再安装。</p>',51)])])}const b=o(i,[["render",c]]);export{u as __pageData,b as default};
